4634	{
4635		struct ieee80211_hw *hw = (struct ieee80211_hw *)data;
4636		struct mwl8k_priv *priv = hw->priv;
4637		int limit;
4638		int i;
4639	
4640		limit = 32;
4641	
4642		spin_lock(&priv->tx_lock);
